fn run(input: u32) -> [u32; 3] {
    let mut l14: u16 = 27464_u16;
    'o15: for x16 in (0_u32..5) {
        l14 = ((input as u16) * l14);
    }
    [0_u32, 0.0_f32.to_bits(), ((63_i8 * (input as i8)) as u32)]
}

